CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

CREATE TYPE role_pengguna            AS ENUM ('Peminjam', 'Penanggung Jawab');
CREATE TYPE kondisi_barang           AS ENUM ('Baik', 'Rusak');
-- Pengembalian & Selesai = fase setelah barang diambil (peminjaman keluar dari tab Dipinjam)
CREATE TYPE status_peminjaman        AS ENUM ('Diajukan', 'Disetujui', 'Dipinjam', 'Ditolak', 'Pengembalian', 'Selesai');
-- 'Terlambat' TIDAK disimpan; dihitung otomatis di view v_pengembalian_detail
CREATE TYPE status_pengembalian      AS ENUM ('Menunggu', 'Dikembalikan', 'Ditolak');
CREATE TYPE status_request_pj        AS ENUM ('Menunggu', 'Disetujui', 'Ditolak');
CREATE TYPE status_request_password  AS ENUM ('Menunggu', 'Dikonfirmasi');


-- Tanggal "hari ini" menurut WIB (server Supabase berzona UTC)
CREATE FUNCTION fn_hari_ini() RETURNS date
LANGUAGE sql STABLE AS $$ SELECT (now() AT TIME ZONE 'Asia/Jakarta')::date $$;

-- Mengisi kolom updated_at
CREATE FUNCTION trg_set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;


-- 2. TABEL (3NF)
CREATE TABLE organisasi (
  id_organisasi   integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nama_organisasi varchar(100) NOT NULL,
  singkatan       varchar(20)  NOT NULL,
  logo_path       text,
  icon            bytea,
  CONSTRAINT uq_organisasi_nama      UNIQUE (nama_organisasi),
  CONSTRAINT uq_organisasi_singkatan UNIQUE (singkatan)
);

CREATE TABLE pengguna (
  nim            varchar(20)  PRIMARY KEY,
  id_organisasi  integer      NOT NULL REFERENCES organisasi (id_organisasi) ON UPDATE CASCADE ON DELETE RESTRICT,
  nama_pengguna  varchar(100) NOT NULL CHECK (btrim(nama_pengguna) <> ''),
  password_hash  text         NOT NULL,
  role           role_pengguna NOT NULL DEFAULT 'Peminjam',
  status_akun    boolean      NOT NULL DEFAULT true,
  created_at     timestamptz  NOT NULL DEFAULT now(),
  updated_at     timestamptz  NOT NULL DEFAULT now(),
  -- hanya hash bcrypt ($2a$10$ + 53 karakter) yang boleh tersimpan
  CONSTRAINT ck_pengguna_hash CHECK (password_hash ~ '^\$2[abxy]\$[0-9]{2}\$.{53}$')
);

CREATE TABLE kategori (
  id_kategori   integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nama_kategori varchar(30) NOT NULL CHECK (btrim(nama_kategori) <> '')
);
-- nama kategori unik tanpa membedakan huruf besar/kecil
CREATE UNIQUE INDEX uq_kategori_nama ON kategori (lower(nama_kategori));

CREATE TABLE inventaris (
  id_inventaris integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  id_organisasi integer NOT NULL REFERENCES organisasi (id_organisasi) ON UPDATE CASCADE ON DELETE RESTRICT,
  id_kategori   integer NOT NULL REFERENCES kategori (id_kategori)     ON UPDATE CASCADE ON DELETE RESTRICT,
  nama_barang   varchar(100) NOT NULL CHECK (btrim(nama_barang) <> ''),
  total_unit    integer NOT NULL CHECK (total_unit BETWEEN 1 AND 999),
  kondisi       kondisi_barang NOT NULL DEFAULT 'Baik',
  deskripsi     text,
  foto_path     text,
  -- soft delete (riwayat peminjaman tetap utuh)
  deleted_at    timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE peminjaman (
  id_peminjaman         integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nim                   varchar(20) NOT NULL REFERENCES pengguna (nim)             ON UPDATE CASCADE ON DELETE RESTRICT,
  id_inventaris         integer     NOT NULL REFERENCES inventaris (id_inventaris) ON UPDATE CASCADE ON DELETE RESTRICT,
  jumlah_pinjam         integer     NOT NULL CHECK (jumlah_pinjam > 0),
  tanggal_pengajuan     date        NOT NULL DEFAULT fn_hari_ini(),
  tgl_mulai             date        NOT NULL,
  tgl_selesai           date        NOT NULL,
  keperluan             varchar(255) NOT NULL CHECK (btrim(keperluan) <> ''),
  status                status_peminjaman NOT NULL DEFAULT 'Diajukan',
  diproses_oleh         varchar(20) REFERENCES pengguna (nim) ON UPDATE CASCADE ON DELETE RESTRICT,
  alasan_penolakan      text,
  tanggal_pengambilan   date,
  foto_pengambilan_path text,
  kondisi_sebelum       kondisi_barang,
  -- 1 hari persiapan sebelum mulai & 1 hari pengecekan setelah selesai (dihitung otomatis)
  tgl_blok_mulai        date GENERATED ALWAYS AS (tgl_mulai - 1)   STORED,
  tgl_blok_selesai      date GENERATED ALWAYS AS (tgl_selesai + 1) STORED,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_pinjam_rentang CHECK (tgl_selesai >= tgl_mulai),
  CONSTRAINT ck_pinjam_h2      CHECK (tgl_mulai >= tanggal_pengajuan + 2),
  CONSTRAINT ck_pinjam_tolak   CHECK (status <> 'Ditolak' OR (alasan_penolakan IS NOT NULL AND diproses_oleh IS NOT NULL)),
  CONSTRAINT ck_pinjam_ambil   CHECK (status NOT IN ('Dipinjam', 'Pengembalian', 'Selesai') OR tanggal_pengambilan IS NOT NULL)
);

-- 1 peminjaman : 0..1 pengembalian. Pengajuan ulang setelah Ditolak memakai baris yang sama.
CREATE TABLE pengembalian (
  id_pengembalian      integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  id_peminjaman        integer NOT NULL UNIQUE REFERENCES peminjaman (id_peminjaman) ON UPDATE CASCADE ON DELETE RESTRICT,
  status               status_pengembalian NOT NULL DEFAULT 'Menunggu',
  tanggal_diajukan     date NOT NULL DEFAULT fn_hari_ini(),
  jumlah_dikembalikan  integer CHECK (jumlah_dikembalikan > 0),
  tanggal_pengembalian date,
  kondisi_kembali      kondisi_barang,
  foto_kondisi_path    text,
  sanksi               text,
  alasan_penolakan     text,
  diproses_oleh        varchar(20) REFERENCES pengguna (nim) ON UPDATE CASCADE ON DELETE RESTRICT,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_kembali_lengkap CHECK (status <> 'Dikembalikan' OR
     (jumlah_dikembalikan IS NOT NULL AND tanggal_pengembalian IS NOT NULL
      AND kondisi_kembali IS NOT NULL AND diproses_oleh IS NOT NULL)),
  CONSTRAINT ck_kembali_tolak CHECK (status <> 'Ditolak' OR (alasan_penolakan IS NOT NULL AND diproses_oleh IS NOT NULL))
);

-- Organisasi pemohon diambil dari pengguna.id_organisasi (tidak diduplikasi => 3NF)
CREATE TABLE request_pj (
  id_request       integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nim              varchar(20) NOT NULL REFERENCES pengguna (nim) ON UPDATE CASCADE ON DELETE RESTRICT,
  lampiran_path    text        NOT NULL,                  -- surat rekomendasi (maks 2 MB, divalidasi BE)
  status           status_request_pj NOT NULL DEFAULT 'Menunggu',
  tanggal_request  date        NOT NULL DEFAULT fn_hari_ini(),
  diproses_oleh    varchar(20) REFERENCES pengguna (nim) ON UPDATE CASCADE ON DELETE RESTRICT,
  -- diisi trigger; sumber "Tanggal Disetujui"
  diproses_pada    timestamptz,
  alasan_penolakan text,
  CONSTRAINT ck_request_pj_tolak CHECK (status <> 'Ditolak' OR alasan_penolakan IS NOT NULL),
  CONSTRAINT ck_request_pj_proses CHECK (status = 'Menunggu' OR (diproses_oleh IS NOT NULL AND diproses_pada IS NOT NULL))
);
-- satu pengguna hanya boleh punya satu pengajuan PJ berstatus Menunggu
CREATE UNIQUE INDEX uq_request_pj_menunggu ON request_pj (nim) WHERE status = 'Menunggu';

CREATE TABLE request_password (
  id_request_password integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nim                 varchar(20) NOT NULL REFERENCES pengguna (nim) ON UPDATE CASCADE ON DELETE RESTRICT,
  no_whatsapp         varchar(20) NOT NULL CHECK (no_whatsapp ~ '^[0-9+]{8,20}$'),
  status              status_request_password NOT NULL DEFAULT 'Menunggu',
  tanggal_request     date NOT NULL DEFAULT fn_hari_ini(),
  token_hash          text,                               -- SHA-256 token; token asli tidak disimpan
  token_kedaluwarsa   timestamptz,
  token_dipakai_pada  timestamptz,                        -- tautan hanya berlaku satu kali
  pesan_terkirim      text,
  diproses_oleh       varchar(20) REFERENCES pengguna (nim) ON UPDATE CASCADE ON DELETE RESTRICT,
  dikonfirmasi_pada   timestamptz,
  CONSTRAINT ck_reqpass_konfirmasi CHECK (status <> 'Dikonfirmasi' OR (token_hash IS NOT NULL AND diproses_oleh IS NOT NULL))
);
CREATE UNIQUE INDEX uq_request_password_menunggu ON request_password (nim) WHERE status = 'Menunggu';

-- Jejak audit perubahan status (diisi trigger)
CREATE TABLE log_aktivitas (
  id_log      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tabel       text NOT NULL,
  id_record   text NOT NULL,
  status_lama text,
  status_baru text,
  oleh        varchar(20),
  waktu       timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- 3. INDEKS (optimasi query)
-- ---------------------------------------------------------------------
CREATE INDEX idx_pengguna_org          ON pengguna (id_organisasi);
CREATE INDEX idx_inventaris_org_aktif  ON inventaris (id_organisasi) WHERE deleted_at IS NULL;
CREATE INDEX idx_inventaris_kategori   ON inventaris (id_kategori);
CREATE INDEX idx_peminjaman_nim_status ON peminjaman (nim, status);
-- dipakai fn_kalender_ketersediaan: hanya peminjaman yang menahan kuota
CREATE INDEX idx_peminjaman_kuota ON peminjaman (id_inventaris, tgl_blok_mulai, tgl_blok_selesai)
  WHERE status IN ('Diajukan', 'Disetujui', 'Dipinjam', 'Pengembalian');
CREATE INDEX idx_peminjaman_inventaris ON peminjaman (id_inventaris, status);
CREATE INDEX idx_request_pj_nim        ON request_pj (nim);
CREATE INDEX idx_request_password_nim  ON request_password (nim);
CREATE INDEX idx_log_record            ON log_aktivitas (tabel, id_record);

-- ---------------------------------------------------------------------
-- 4. FUNGSI KALENDER KETERSEDIAAN (query lanjutan: JOIN + agregasi)
--    Satu fungsi dipakai FE (kalender form) DAN trigger validasi kuota.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_kalender_ketersediaan(
  p_id_inventaris integer, p_dari date, p_sampai date, p_kecuali integer DEFAULT NULL)
RETURNS TABLE (tanggal date, total_unit integer, unit_dipinjam integer, unit_persiapan integer,
               terpakai integer, sisa_unit integer, penanda text)
LANGUAGE sql STABLE SET search_path = public AS $$
  WITH hari AS (
    SELECT g::date AS tgl
    FROM generate_series(p_dari::timestamp, p_sampai::timestamp, interval '1 day') g
  ),
  pakai AS (
    SELECT h.tgl,
           COALESCE(SUM(p.jumlah_pinjam) FILTER (WHERE
              (h.tgl BETWEEN p.tgl_mulai AND p.tgl_selesai)
              OR (p.status IN ('Dipinjam', 'Pengembalian') AND p.tgl_selesai < fn_hari_ini())), 0)::integer AS dipinjam,
           COALESCE(SUM(p.jumlah_pinjam), 0)::integer AS total_pakai
    FROM hari h
    LEFT JOIN peminjaman p
           ON p.id_inventaris = p_id_inventaris
          AND p.status IN ('Diajukan', 'Disetujui', 'Dipinjam', 'Pengembalian')
          AND (p_kecuali IS NULL OR p.id_peminjaman <> p_kecuali)
          AND h.tgl >= p.tgl_blok_mulai
          -- barang terlambat tetap menahan kuota sampai dikembalikan
          AND (h.tgl <= p.tgl_blok_selesai
               OR (p.status IN ('Dipinjam', 'Pengembalian') AND p.tgl_selesai < fn_hari_ini()))
    GROUP BY h.tgl
  )
  SELECT k.tgl, i.total_unit, k.dipinjam, k.total_pakai - k.dipinjam, k.total_pakai,
         GREATEST(i.total_unit - k.total_pakai, 0),
         CASE WHEN i.total_unit - k.total_pakai <= 0 THEN 'Tidak tersedia'
              WHEN k.total_pakai = 0                 THEN 'Tersedia'
              WHEN k.dipinjam = 0                    THEN 'Persiapan/pengecekan'
              ELSE 'Sebagian terpakai' END
  FROM pakai k
  JOIN inventaris i ON i.id_inventaris = p_id_inventaris
  ORDER BY k.tgl
$$;

-- Batas maksimal jumlah unit untuk rentang tanggal terpilih (field Jumlah Unit pada form)
CREATE FUNCTION fn_maks_unit_tersedia(p_id_inventaris integer, p_mulai date, p_selesai date)
RETURNS integer LANGUAGE sql STABLE SET search_path = public AS $$
  SELECT COALESCE(MIN(sisa_unit), 0)
  FROM fn_kalender_ketersediaan(p_id_inventaris, p_mulai - 1, p_selesai + 1)
$$;

-- Dialog "Jadwal berdekatan dengan peminjaman sebelumnya"
CREATE FUNCTION fn_jadwal_berdekatan(p_id_inventaris integer, p_mulai date, p_selesai date)
RETURNS boolean LANGUAGE sql STABLE SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM peminjaman p
    WHERE p.id_inventaris = p_id_inventaris
      AND p.status IN ('Diajukan', 'Disetujui', 'Dipinjam', 'Pengembalian')
      AND p.tgl_blok_mulai <= p_selesai + 1
      AND p.tgl_blok_selesai >= p_mulai - 1)
$$;

-- Memastikan aktor adalah PJ aktif (opsional: dari OKI tertentu). Mengembalikan id OKI-nya.
CREATE FUNCTION fn_pastikan_pj(p_nim varchar, p_id_organisasi integer DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql STABLE SET search_path = public AS $$
DECLARE v_org integer;
BEGIN
  SELECT u.id_organisasi INTO v_org
  FROM pengguna u
  WHERE u.nim = p_nim AND u.status_akun AND u.role = 'Penanggung Jawab';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Aksi ini hanya untuk Penanggung Jawab aktif';
  END IF;
  IF p_id_organisasi IS NOT NULL AND v_org <> p_id_organisasi THEN
    RAISE EXCEPTION 'Anda hanya dapat mengelola data milik OKI Anda sendiri';
  END IF;
  RETURN v_org;
END $$;

-- ---------------------------------------------------------------------
-- 5. VIEW  (semua security_invoker; tidak ada kolom password_hash)
-- ---------------------------------------------------------------------
-- 5.1 Inventaris + ketersediaan hari ini (PJ: Kelola Inventaris)
CREATE VIEW v_inventaris WITH (security_invoker = true) AS
SELECT i.id_inventaris, i.nama_barang, i.id_kategori, k.nama_kategori,
       i.id_organisasi, o.nama_organisasi, o.singkatan, o.logo_path,
       i.total_unit,
       COALESCE(d.unit_keluar, 0)::integer                      AS unit_keluar,
       (i.total_unit - COALESCE(d.unit_keluar, 0))::integer     AS jumlah_tersedia,
       i.kondisi,
       CASE WHEN i.total_unit - COALESCE(d.unit_keluar, 0) > 0 THEN 'Tersedia' ELSE 'Dipinjam' END AS ketersediaan,
       i.deskripsi, i.foto_path, i.created_at
FROM inventaris i
JOIN kategori  k ON k.id_kategori   = i.id_kategori
JOIN organisasi o ON o.id_organisasi = i.id_organisasi
LEFT JOIN (SELECT id_inventaris, SUM(jumlah_pinjam) AS unit_keluar
           FROM peminjaman WHERE status IN ('Dipinjam', 'Pengembalian')
           GROUP BY id_inventaris) d ON d.id_inventaris = i.id_inventaris
WHERE i.deleted_at IS NULL;

-- 5.2 Katalog (barang Rusak tidak tampil). BE menambah: WHERE id_organisasi <> <OKI user>
CREATE VIEW v_katalog_inventaris WITH (security_invoker = true) AS
SELECT * FROM v_inventaris WHERE kondisi = 'Baik';

-- 5.3 Jadwal peminjaman pada halaman detail barang
CREATE VIEW v_jadwal_peminjaman WITH (security_invoker = true) AS
SELECT p.id_inventaris, p.id_peminjaman, p.tgl_mulai, p.tgl_selesai, p.keperluan, p.jumlah_pinjam,
       CASE WHEN p.status = 'Pengembalian' THEN 'Dipinjam' ELSE p.status::text END AS status
FROM peminjaman p
WHERE p.status IN ('Diajukan', 'Disetujui', 'Dipinjam', 'Pengembalian');

-- 5.4 Detail peminjaman: dipakai Peminjam (filter nim_peminjam) dan PJ (filter id_organisasi_pemilik)
CREATE VIEW v_peminjaman_detail WITH (security_invoker = true) AS
SELECT p.id_peminjaman,
       p.nim AS nim_peminjam, u.nama_pengguna AS nama_peminjam,
       u.id_organisasi AS id_organisasi_peminjam, uo.singkatan AS oki_peminjam,
       p.id_inventaris, i.nama_barang,
       i.id_organisasi AS id_organisasi_pemilik, oo.singkatan AS oki_pemilik, oo.logo_path AS logo_pemilik,
       p.jumlah_pinjam, p.tanggal_pengajuan, p.tgl_mulai, p.tgl_selesai, p.tanggal_pengambilan,
       p.keperluan, p.status, p.alasan_penolakan,
       p.diproses_oleh AS nim_pemroses, pj.nama_pengguna AS nama_pemroses,
       p.foto_pengambilan_path, p.created_at
FROM peminjaman p
JOIN pengguna  u  ON u.nim = p.nim
JOIN organisasi uo ON uo.id_organisasi = u.id_organisasi
JOIN inventaris i ON i.id_inventaris = p.id_inventaris
JOIN organisasi oo ON oo.id_organisasi = i.id_organisasi
LEFT JOIN pengguna pj ON pj.nim = p.diproses_oleh;

-- 5.5 Pengembalian: baris tabel + peminjaman Dipinjam yang lewat tenggat => 'Terlambat'
CREATE VIEW v_pengembalian_detail WITH (security_invoker = true) AS
SELECT g.id_pengembalian, d.id_peminjaman, d.nim_peminjam, d.nama_peminjam, d.oki_peminjam,
       d.id_organisasi_pemilik, d.oki_pemilik, d.nama_barang, d.jumlah_pinjam,
       d.tgl_mulai, d.tanggal_pengambilan, d.tgl_selesai, d.keperluan,
       g.tanggal_diajukan, g.tanggal_pengembalian AS tanggal_dikembalikan,
       g.status::text AS status,
       (COALESCE(g.tanggal_pengembalian, g.tanggal_diajukan) > d.tgl_selesai) AS lewat_tenggat,
       g.jumlah_dikembalikan, g.kondisi_kembali, g.foto_kondisi_path, g.sanksi,
       g.alasan_penolakan, g.diproses_oleh AS nim_pemroses, pj.nama_pengguna AS nama_pemroses
FROM pengembalian g
JOIN v_peminjaman_detail d ON d.id_peminjaman = g.id_peminjaman
LEFT JOIN pengguna pj ON pj.nim = g.diproses_oleh
UNION ALL
SELECT NULL::integer, d.id_peminjaman, d.nim_peminjam, d.nama_peminjam, d.oki_peminjam,
       d.id_organisasi_pemilik, d.oki_pemilik, d.nama_barang, d.jumlah_pinjam,
       d.tgl_mulai, d.tanggal_pengambilan, d.tgl_selesai, d.keperluan,
       NULL::date, NULL::date,
       'Terlambat', true,
       NULL::integer, NULL::kondisi_barang, NULL::text, NULL::text,
       NULL::text, NULL::varchar, NULL::varchar
FROM v_peminjaman_detail d
WHERE d.status = 'Dipinjam' AND d.tgl_selesai < fn_hari_ini();

-- 5.6 Pengajuan PJ (Peminjam: filter nim_pemohon; PJ: filter id_organisasi_pemohon)
CREATE VIEW v_request_pj_detail WITH (security_invoker = true) AS
SELECT r.id_request, r.nim AS nim_pemohon, u.nama_pengguna AS nama_pemohon,
       u.id_organisasi AS id_organisasi_pemohon, o.singkatan AS oki_pemohon, o.logo_path,
       r.tanggal_request, r.status, r.lampiran_path, r.alasan_penolakan,
       r.diproses_oleh AS nim_pemroses, pj.nama_pengguna AS nama_pemroses,
       (r.diproses_pada AT TIME ZONE 'Asia/Jakarta')::date AS tanggal_diproses   -- = Tanggal Disetujui / Ditolak
FROM request_pj r
JOIN pengguna u ON u.nim = r.nim
JOIN organisasi o ON o.id_organisasi = u.id_organisasi
LEFT JOIN pengguna pj ON pj.nim = r.diproses_oleh;

-- 5.7 Request password (tab List Request Password)
CREATE VIEW v_request_password_detail WITH (security_invoker = true) AS
SELECT r.id_request_password, r.nim, u.nama_pengguna, u.id_organisasi AS id_organisasi_pemohon,
       o.singkatan AS oki_pemohon, r.no_whatsapp, r.tanggal_request, r.status,
       r.pesan_terkirim, r.diproses_oleh AS nim_pemroses, r.dikonfirmasi_pada
FROM request_password r
JOIN pengguna u ON u.nim = r.nim
JOIN organisasi o ON o.id_organisasi = u.id_organisasi;

-- 5.8 Daftar pengguna TANPA password_hash (Kelola Pengguna)
CREATE VIEW v_pengguna AS
SELECT u.nim, u.nama_pengguna, u.id_organisasi, o.nama_organisasi, o.singkatan, o.logo_path,
       u.role, u.status_akun
FROM pengguna u JOIN organisasi o ON o.id_organisasi = u.id_organisasi;
ALTER VIEW v_pengguna SET (security_invoker = true);

-- 5.9 Kartu ringkasan Dashboard Peminjam (satu baris per NIM)
CREATE VIEW v_dashboard_peminjam WITH (security_invoker = true) AS
SELECT u.nim,
       pm.total::integer        AS total_peminjaman,
       rp.total::integer        AS total_pengajuan_pj,
       pm.disetujui::integer    AS total_disetujui,
       pm.ditolak::integer      AS total_ditolak,
       pg.dikembalikan::integer AS total_dikembalikan,
       pg.terlambat::integer    AS total_terlambat
FROM pengguna u
CROSS JOIN LATERAL (
  SELECT COUNT(*) AS total,
         COUNT(*) FILTER (WHERE status IN ('Disetujui', 'Dipinjam', 'Pengembalian', 'Selesai')) AS disetujui,
         COUNT(*) FILTER (WHERE status = 'Ditolak') AS ditolak
  FROM peminjaman WHERE nim = u.nim) pm
CROSS JOIN LATERAL (SELECT COUNT(*) AS total FROM request_pj WHERE nim = u.nim) rp
CROSS JOIN LATERAL (
  SELECT COUNT(*) FILTER (WHERE status = 'Dikembalikan') AS dikembalikan,
         COUNT(*) FILTER (WHERE status = 'Terlambat')    AS terlambat
  FROM v_pengembalian_detail WHERE nim_peminjam = u.nim) pg;

-- 5.10 Kartu ringkasan Dashboard PJ + angka badge sidebar (satu baris per OKI)
CREATE VIEW v_dashboard_pj WITH (security_invoker = true) AS
SELECT o.id_organisasi,
  (SELECT COUNT(*) FROM v_peminjaman_detail d WHERE d.id_organisasi_pemilik = o.id_organisasi AND d.status = 'Diajukan')::integer AS pengajuan,
  (SELECT COUNT(*) FROM v_inventaris v WHERE v.id_organisasi = o.id_organisasi AND v.kondisi = 'Rusak')::integer AS rusak,
  (SELECT COUNT(*) FROM v_inventaris v WHERE v.id_organisasi = o.id_organisasi AND v.kondisi = 'Baik' AND v.ketersediaan = 'Tersedia')::integer AS tersedia,
  (SELECT COUNT(*) FROM v_pengembalian_detail g WHERE g.id_organisasi_pemilik = o.id_organisasi AND g.status = 'Terlambat')::integer AS terlambat,
  (SELECT COALESCE(SUM(i.total_unit), 0) FROM inventaris i WHERE i.id_organisasi = o.id_organisasi AND i.deleted_at IS NULL)::integer AS total_unit,
  (SELECT COUNT(*) FROM request_pj r JOIN pengguna u ON u.nim = r.nim
    WHERE u.id_organisasi = o.id_organisasi AND r.status = 'Menunggu')::integer AS persetujuan_pj,
  (SELECT COUNT(*) FROM v_pengembalian_detail g WHERE g.id_organisasi_pemilik = o.id_organisasi AND g.status = 'Menunggu')::integer AS pengembalian_menunggu,
  (SELECT COUNT(*) FROM request_password rq JOIN pengguna u ON u.nim = rq.nim
    WHERE u.id_organisasi = o.id_organisasi AND rq.status = 'Menunggu')::integer AS request_password_menunggu
FROM organisasi o;

-- ---------------------------------------------------------------------
-- 6. TRIGGER
-- ---------------------------------------------------------------------
-- 6.1 Password default = NIM (di-hash). Insert dengan password polos ditolak oleh CHECK.
CREATE FUNCTION trg_pengguna_password_default() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, extensions AS $$
BEGIN
  IF NEW.password_hash IS NULL OR btrim(NEW.password_hash) = '' THEN
    NEW.password_hash := crypt(NEW.nim, gen_salt('bf', 10));
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_pengguna_password BEFORE INSERT ON pengguna
  FOR EACH ROW EXECUTE FUNCTION trg_pengguna_password_default();

CREATE TRIGGER trg_pengguna_updated    BEFORE UPDATE ON pengguna    FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at();
CREATE TRIGGER trg_inventaris_updated  BEFORE UPDATE ON inventaris  FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at();
CREATE TRIGGER trg_peminjaman_updated  BEFORE UPDATE ON peminjaman  FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at();
CREATE TRIGGER trg_pengembalian_updated BEFORE UPDATE ON pengembalian FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at();

-- 6.2 Validasi pengajuan peminjaman (aturan kalender, kuota per hari, kondisi, OKI)
CREATE FUNCTION trg_validasi_peminjaman() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
DECLARE
  v_inv  inventaris%ROWTYPE;
  v_user pengguna%ROWTYPE;
BEGIN
  NEW.status := 'Diajukan';
  NEW.tanggal_pengajuan := fn_hari_ini();
  NEW.diproses_oleh := NULL;  NEW.alasan_penolakan := NULL;
  NEW.tanggal_pengambilan := NULL;  NEW.kondisi_sebelum := NULL;

  SELECT * INTO v_user FROM pengguna WHERE nim = NEW.nim;
  IF NOT FOUND OR NOT v_user.status_akun THEN
    RAISE EXCEPTION 'Akun peminjam tidak ditemukan atau nonaktif';
  END IF;

  -- kunci baris barang agar pengajuan bersamaan diproses berurutan (cegah over-booking)
  SELECT * INTO v_inv FROM inventaris WHERE id_inventaris = NEW.id_inventaris AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Barang tidak ditemukan'; END IF;
  IF v_inv.kondisi = 'Rusak' THEN RAISE EXCEPTION 'Barang berkondisi Rusak tidak dapat dipinjam'; END IF;
  IF v_inv.id_organisasi = v_user.id_organisasi THEN RAISE EXCEPTION 'Barang milik OKI Anda tidak dapat dipinjam'; END IF;
  IF NEW.tgl_mulai < fn_hari_ini() + 2 THEN RAISE EXCEPTION 'Tanggal mulai paling cepat H+2 dari tanggal pengajuan'; END IF;
  IF NEW.tgl_selesai < NEW.tgl_mulai THEN RAISE EXCEPTION 'Tanggal selesai tidak boleh sebelum tanggal mulai'; END IF;

  IF EXISTS (SELECT 1 FROM fn_kalender_ketersediaan(NEW.id_inventaris, NEW.tgl_mulai - 1, NEW.tgl_selesai + 1) k
             WHERE k.sisa_unit < NEW.jumlah_pinjam) THEN
    RAISE EXCEPTION 'Kuota unit tidak mencukupi pada tanggal yang dipilih';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_peminjaman_validasi BEFORE INSERT ON peminjaman
  FOR EACH ROW EXECUTE FUNCTION trg_validasi_peminjaman();

-- 6.3 Mesin status peminjaman: hanya transisi yang sah; catat kondisi saat barang diambil
CREATE FUNCTION trg_peminjaman_transisi() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF (OLD.status::text || '>' || NEW.status::text) NOT IN
     ('Diajukan>Disetujui', 'Diajukan>Ditolak', 'Disetujui>Dipinjam', 'Dipinjam>Pengembalian', 'Pengembalian>Selesai') THEN
    RAISE EXCEPTION 'Perubahan status % menjadi % tidak diizinkan', OLD.status, NEW.status;
  END IF;
  IF NEW.status IN ('Disetujui', 'Ditolak') AND NEW.diproses_oleh IS NULL THEN
    RAISE EXCEPTION 'Penanggung jawab pemroses wajib dicatat';
  END IF;
  IF NEW.status = 'Dipinjam' THEN
    SELECT kondisi INTO NEW.kondisi_sebelum FROM inventaris WHERE id_inventaris = NEW.id_inventaris;
    NEW.tanggal_pengambilan := COALESCE(NEW.tanggal_pengambilan, fn_hari_ini());
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_peminjaman_transisi BEFORE UPDATE OF status ON peminjaman
  FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status)
  EXECUTE FUNCTION trg_peminjaman_transisi();

-- 6.4 Jumlah unit tidak boleh turun di bawah puncak pemakaian peminjaman aktif/terjadwal
CREATE FUNCTION trg_validasi_ubah_inventaris() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_akhir date; v_puncak integer;
BEGIN
  SELECT GREATEST(COALESCE(MAX(tgl_blok_selesai), fn_hari_ini()), fn_hari_ini()) INTO v_akhir
  FROM peminjaman
  WHERE id_inventaris = NEW.id_inventaris AND status IN ('Diajukan', 'Disetujui', 'Dipinjam', 'Pengembalian');
  SELECT COALESCE(MAX(terpakai), 0) INTO v_puncak
  FROM fn_kalender_ketersediaan(NEW.id_inventaris, fn_hari_ini(), v_akhir);
  IF NEW.total_unit < v_puncak THEN
    RAISE EXCEPTION 'Jumlah unit tidak boleh kurang dari % unit yang terpakai pada peminjaman aktif/terjadwal', v_puncak;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_inventaris_total BEFORE UPDATE OF total_unit ON inventaris
  FOR EACH ROW WHEN (NEW.total_unit < OLD.total_unit)
  EXECUTE FUNCTION trg_validasi_ubah_inventaris();

-- 6.5 Pengembalian: hanya untuk peminjaman Dipinjam
CREATE FUNCTION trg_validasi_pengembalian() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM peminjaman WHERE id_peminjaman = NEW.id_peminjaman AND status = 'Dipinjam') THEN
    RAISE EXCEPTION 'Pengembalian hanya dapat diajukan untuk peminjaman berstatus Dipinjam';
  END IF;
  NEW.status := 'Menunggu';
  RETURN NEW;
END $$;
CREATE TRIGGER trg_pengembalian_validasi BEFORE INSERT ON pengembalian
  FOR EACH ROW EXECUTE FUNCTION trg_validasi_pengembalian();

-- 6.6 Sinkronisasi otomatis lintas tabel saat pengembalian berubah
--     Menunggu     => peminjaman jadi 'Pengembalian'
--     Dikembalikan => kondisi inventaris diperbarui + peminjaman 'Selesai' (kuota dilepas)
CREATE FUNCTION trg_pengembalian_sinkron() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NEW.status = 'Menunggu' THEN
    UPDATE peminjaman SET status = 'Pengembalian'
    WHERE id_peminjaman = NEW.id_peminjaman AND status = 'Dipinjam';
  ELSIF NEW.status = 'Dikembalikan' THEN
    UPDATE inventaris SET kondisi = NEW.kondisi_kembali
    WHERE id_inventaris = (SELECT id_inventaris FROM peminjaman WHERE id_peminjaman = NEW.id_peminjaman);
    UPDATE peminjaman SET status = 'Selesai'
    WHERE id_peminjaman = NEW.id_peminjaman AND status = 'Pengembalian';
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER trg_pengembalian_sinkron AFTER INSERT OR UPDATE OF status ON pengembalian
  FOR EACH ROW EXECUTE FUNCTION trg_pengembalian_sinkron();

-- 6.7 Pengajuan PJ: pemohon harus Peminjam aktif; saat disetujui, role otomatis naik
CREATE FUNCTION trg_request_pj_validasi() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pengguna WHERE nim = NEW.nim AND status_akun AND role = 'Peminjam') THEN
    RAISE EXCEPTION 'Hanya pengguna aktif berrole Peminjam yang dapat mengajukan PJ';
  END IF;
  NEW.status := 'Menunggu';
  RETURN NEW;
END $$;
CREATE TRIGGER trg_request_pj_validasi BEFORE INSERT ON request_pj
  FOR EACH ROW EXECUTE FUNCTION trg_request_pj_validasi();

CREATE FUNCTION trg_request_pj_proses() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF OLD.status <> 'Menunggu' THEN
    RAISE EXCEPTION 'Pengajuan sudah diproses dan tidak dapat diproses ulang';
  END IF;
  NEW.diproses_pada := now();
  IF NEW.status = 'Disetujui' THEN
    UPDATE pengguna SET role = 'Penanggung Jawab' WHERE nim = NEW.nim;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_request_pj_proses BEFORE UPDATE OF status ON request_pj
  FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status)
  EXECUTE FUNCTION trg_request_pj_proses();

-- 6.8 Audit trail perubahan status (dipasang di 4 tabel; argumen = nama kolom PK)
CREATE FUNCTION trg_log_status() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_baru jsonb := to_jsonb(NEW);
BEGIN
  IF TG_OP = 'UPDATE' AND v_baru->>'status' IS NOT DISTINCT FROM to_jsonb(OLD)->>'status' THEN
    RETURN NULL;
  END IF;
  INSERT INTO log_aktivitas (tabel, id_record, status_lama, status_baru, oleh)
  VALUES (TG_TABLE_NAME, v_baru->>TG_ARGV[0],
          CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD)->>'status' END,
          v_baru->>'status',
          COALESCE(v_baru->>'diproses_oleh', v_baru->>'nim'));
  RETURN NULL;
END $$;
CREATE TRIGGER trg_log_peminjaman  AFTER INSERT OR UPDATE OF status ON peminjaman        FOR EACH ROW EXECUTE FUNCTION trg_log_status('id_peminjaman');
CREATE TRIGGER trg_log_pengembalian AFTER INSERT OR UPDATE OF status ON pengembalian      FOR EACH ROW EXECUTE FUNCTION trg_log_status('id_pengembalian');
CREATE TRIGGER trg_log_request_pj  AFTER INSERT OR UPDATE OF status ON request_pj        FOR EACH ROW EXECUTE FUNCTION trg_log_status('id_request');
CREATE TRIGGER trg_log_request_pass AFTER INSERT OR UPDATE OF status ON request_password FOR EACH ROW EXECUTE FUNCTION trg_log_status('id_request_password');

-- ---------------------------------------------------------------------
-- 7. STORED PROCEDURE (fungsi plpgsql, dipanggil BE: SELECT sp_xxx(...))
--    Catatan: PostgREST/Supabase rpc() hanya bisa memanggil FUNCTION, bukan
--    CREATE PROCEDURE; karena itu proses bisnis ditulis sebagai fungsi.
--    CREATE PROCEDURE sungguhan ada di bagian 8 (sp_refresh_laporan).
-- ---------------------------------------------------------------------

-- 7.1 Autentikasi -----------------------------------------------------
CREATE FUNCTION fn_login(p_nim varchar, p_password text)
RETURNS TABLE (nim varchar, nama_pengguna varchar, role role_pengguna,
               id_organisasi integer, nama_organisasi varchar, singkatan varchar)
LANGUAGE plpgsql STABLE SET search_path = public, extensions AS $$
#variable_conflict use_column
DECLARE u pengguna%ROWTYPE;
BEGIN
  SELECT * INTO u FROM pengguna x WHERE x.nim = p_nim;
  -- pesan sama untuk NIM salah / password salah (tidak membocorkan keberadaan NIM)
  IF NOT FOUND OR u.password_hash <> crypt(p_password, u.password_hash) THEN
    RAISE EXCEPTION 'NIM atau password salah';
  END IF;
  IF NOT u.status_akun THEN
    RAISE EXCEPTION 'Akun nonaktif, hubungi penanggung jawab';
  END IF;
  RETURN QUERY
    SELECT u.nim, u.nama_pengguna, u.role, o.id_organisasi, o.nama_organisasi, o.singkatan
    FROM organisasi o WHERE o.id_organisasi = u.id_organisasi;
END $$;

CREATE FUNCTION sp_ubah_password(p_nim varchar, p_password_lama text, p_password_baru text)
RETURNS void LANGUAGE plpgsql SET search_path = public, extensions AS $$
DECLARE v_hash text;
BEGIN
  SELECT password_hash INTO v_hash FROM pengguna WHERE nim = p_nim;
  IF NOT FOUND OR v_hash <> crypt(p_password_lama, v_hash) THEN
    RAISE EXCEPTION 'Password saat ini salah';
  END IF;
  IF length(p_password_baru) < 8 THEN RAISE EXCEPTION 'Password baru minimal 8 karakter'; END IF;
  UPDATE pengguna SET password_hash = crypt(p_password_baru, gen_salt('bf', 10)) WHERE nim = p_nim;
END $$;

-- 7.2 Lupa password ---------------------------------------------------
CREATE FUNCTION sp_ajukan_lupa_password(p_nim varchar, p_no_whatsapp varchar)
RETURNS integer LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_id integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pengguna WHERE nim = p_nim) THEN
    RAISE EXCEPTION 'NIM tidak terdaftar';
  END IF;
  INSERT INTO request_password (nim, no_whatsapp) VALUES (p_nim, p_no_whatsapp)
  ON CONFLICT (nim) WHERE status = 'Menunggu' DO UPDATE SET no_whatsapp = EXCLUDED.no_whatsapp
  RETURNING id_request_password INTO v_id;
  RETURN v_id;     -- diteruskan ke PJ dari OKI yang sama (filter id_organisasi_pemohon di BE)
END $$;

-- PJ klik "Setujui": buat token acak sekali pakai; MENGEMBALIKAN token asli satu kali saja
CREATE FUNCTION sp_proses_request_password(p_id_request integer, p_pj_nim varchar)
RETURNS text LANGUAGE plpgsql SET search_path = public, extensions AS $$
DECLARE v_org integer; v_status status_request_password; v_token text;
BEGIN
  SELECT u.id_organisasi, r.status INTO v_org, v_status
  FROM request_password r JOIN pengguna u ON u.nim = r.nim
  WHERE r.id_request_password = p_id_request FOR UPDATE OF r;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request password tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);
  IF v_status <> 'Menunggu' THEN RAISE EXCEPTION 'Request sudah dikonfirmasi'; END IF;

  v_token := encode(gen_random_bytes(32), 'hex');
  UPDATE request_password
     SET token_hash = encode(digest(v_token, 'sha256'), 'hex'),
         token_kedaluwarsa = now() + interval '24 hours',
         token_dipakai_pada = NULL,
         diproses_oleh = p_pj_nim
   WHERE id_request_password = p_id_request;
  RETURN v_token;
END $$;

CREATE FUNCTION sp_konfirmasi_request_password(p_id_request integer, p_pj_nim varchar, p_pesan text)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer; v_hash text;
BEGIN
  SELECT u.id_organisasi, r.token_hash INTO v_org, v_hash
  FROM request_password r JOIN pengguna u ON u.nim = r.nim
  WHERE r.id_request_password = p_id_request AND r.status = 'Menunggu' FOR UPDATE OF r;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request tidak ditemukan atau sudah dikonfirmasi'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);
  IF v_hash IS NULL THEN RAISE EXCEPTION 'Proses (setujui) request terlebih dahulu untuk membuat tautan'; END IF;
  UPDATE request_password
     SET status = 'Dikonfirmasi', pesan_terkirim = p_pesan,
         diproses_oleh = p_pj_nim, dikonfirmasi_pada = now()
   WHERE id_request_password = p_id_request;
END $$;

-- Halaman reset password: token sekali pakai, kedaluwarsa 24 jam
CREATE FUNCTION sp_reset_password_dengan_token(p_token text, p_password_baru text)
RETURNS void LANGUAGE plpgsql SET search_path = public, extensions AS $$
DECLARE v_id integer; v_nim varchar;
BEGIN
  IF length(p_password_baru) < 8 THEN RAISE EXCEPTION 'Password baru minimal 8 karakter'; END IF;
  SELECT id_request_password, nim INTO v_id, v_nim
  FROM request_password
  WHERE token_hash = encode(digest(p_token, 'sha256'), 'hex')
    AND status = 'Dikonfirmasi' AND token_dipakai_pada IS NULL AND token_kedaluwarsa > now()
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tautan tidak valid, sudah dipakai, atau kedaluwarsa'; END IF;
  UPDATE pengguna SET password_hash = crypt(p_password_baru, gen_salt('bf', 10)) WHERE nim = v_nim;
  UPDATE request_password SET token_dipakai_pada = now() WHERE id_request_password = v_id;
END $$;

-- 7.3 Kelola pengguna (PJ hanya mengelola pengguna dari OKI-nya sendiri;
--     BE memfilter v_pengguna dengan WHERE id_organisasi = <OKI PJ>) --------
-- Password default = NIM (di-hash oleh trigger trg_pengguna_password)
CREATE FUNCTION sp_tambah_pengguna(p_pj_nim varchar, p_nim varchar, p_nama varchar,
                                   p_id_organisasi integer, p_role role_pengguna DEFAULT 'Peminjam')
RETURNS varchar LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  PERFORM fn_pastikan_pj(p_pj_nim, p_id_organisasi);   -- PJ hanya menambah pengguna ke OKI-nya sendiri
  INSERT INTO pengguna (nim, id_organisasi, nama_pengguna, role) VALUES (p_nim, p_id_organisasi, p_nama, p_role);
  RETURN p_nim;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'NIM sudah terdaftar';
END $$;

CREATE FUNCTION sp_ubah_pengguna(p_pj_nim varchar, p_nim_lama varchar, p_nim_baru varchar,
                                 p_nama varchar, p_id_organisasi integer, p_role role_pengguna)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer;
BEGIN
  SELECT id_organisasi INTO v_org FROM pengguna WHERE nim = p_nim_lama FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pengguna tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);            -- hanya pengguna dari OKI PJ sendiri
  IF p_id_organisasi <> v_org THEN
    RAISE EXCEPTION 'Pengguna tidak dapat dipindahkan ke OKI lain';
  END IF;
  UPDATE pengguna SET nim = p_nim_baru, nama_pengguna = p_nama, role = p_role
  WHERE nim = p_nim_lama;                      -- nim berubah => FK ikut berubah (ON UPDATE CASCADE)
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'NIM sudah digunakan';
END $$;

CREATE FUNCTION sp_set_status_akun(p_pj_nim varchar, p_nim varchar, p_aktif boolean)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer;
BEGIN
  SELECT id_organisasi INTO v_org FROM pengguna WHERE nim = p_nim FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pengguna tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);            -- hanya pengguna dari OKI PJ sendiri
  IF p_nim = p_pj_nim AND NOT p_aktif THEN RAISE EXCEPTION 'Anda tidak dapat menonaktifkan akun sendiri'; END IF;
  UPDATE pengguna SET status_akun = p_aktif WHERE nim = p_nim;
END $$;

-- 7.4 Inventaris ------------------------------------------------------
CREATE FUNCTION sp_hapus_inventaris(p_id_inventaris integer, p_pj_nim varchar)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer;
BEGIN
  SELECT id_organisasi INTO v_org FROM inventaris WHERE id_inventaris = p_id_inventaris AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Barang tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);
  IF EXISTS (SELECT 1 FROM peminjaman WHERE id_inventaris = p_id_inventaris
             AND status IN ('Diajukan', 'Disetujui', 'Dipinjam', 'Pengembalian')) THEN
    RAISE EXCEPTION 'Barang tidak dapat dihapus karena masih memiliki peminjaman aktif atau terjadwal';
  END IF;
  UPDATE inventaris SET deleted_at = now() WHERE id_inventaris = p_id_inventaris;
END $$;

-- 7.5 Peminjaman ------------------------------------------------------
-- Semua validasi (H+2, kuota/hari, kondisi, OKI sendiri) dijalankan trigger trg_peminjaman_validasi
CREATE FUNCTION sp_ajukan_peminjaman(p_nim varchar, p_id_inventaris integer, p_jumlah integer,
                                     p_tgl_mulai date, p_tgl_selesai date, p_keperluan varchar)
RETURNS integer LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_id integer;
BEGIN
  INSERT INTO peminjaman (nim, id_inventaris, jumlah_pinjam, tgl_mulai, tgl_selesai, keperluan)
  VALUES (p_nim, p_id_inventaris, p_jumlah, p_tgl_mulai, p_tgl_selesai, p_keperluan)
  RETURNING id_peminjaman INTO v_id;
  RETURN v_id;
END $$;

-- p_aksi: 'Setujui' | 'Tolak'
CREATE FUNCTION sp_proses_peminjaman(p_id_peminjaman integer, p_pj_nim varchar, p_aksi text, p_alasan text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer; v_status status_peminjaman;
BEGIN
  SELECT i.id_organisasi, p.status INTO v_org, v_status
  FROM peminjaman p JOIN inventaris i ON i.id_inventaris = p.id_inventaris
  WHERE p.id_peminjaman = p_id_peminjaman FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Peminjaman tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);          -- hanya PJ OKI pemilik barang
  IF v_status <> 'Diajukan' THEN RAISE EXCEPTION 'Pengajuan sudah diproses'; END IF;

  IF lower(p_aksi) = 'setujui' THEN
    UPDATE peminjaman SET status = 'Disetujui', diproses_oleh = p_pj_nim WHERE id_peminjaman = p_id_peminjaman;
  ELSIF lower(p_aksi) = 'tolak' THEN
    IF btrim(COALESCE(p_alasan, '')) = '' THEN RAISE EXCEPTION 'Alasan penolakan wajib diisi'; END IF;
    UPDATE peminjaman SET status = 'Ditolak', diproses_oleh = p_pj_nim, alasan_penolakan = btrim(p_alasan)
    WHERE id_peminjaman = p_id_peminjaman;          -- kuota otomatis kembali (status Ditolak tidak menahan kuota)
  ELSE
    RAISE EXCEPTION 'Aksi harus Setujui atau Tolak';
  END IF;
END $$;

CREATE FUNCTION sp_pengambilan_barang(p_id_peminjaman integer, p_pj_nim varchar, p_tanggal date, p_foto_path text)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer; v_status status_peminjaman;
BEGIN
  SELECT i.id_organisasi, p.status INTO v_org, v_status
  FROM peminjaman p JOIN inventaris i ON i.id_inventaris = p.id_inventaris
  WHERE p.id_peminjaman = p_id_peminjaman FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Peminjaman tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);
  IF v_status <> 'Disetujui' THEN RAISE EXCEPTION 'Pengambilan hanya untuk peminjaman berstatus Disetujui'; END IF;
  IF p_tanggal IS NULL OR p_foto_path IS NULL THEN RAISE EXCEPTION 'Tanggal dan foto pengambilan wajib diisi'; END IF;
  UPDATE peminjaman SET status = 'Dipinjam', tanggal_pengambilan = p_tanggal, foto_pengambilan_path = p_foto_path
  WHERE id_peminjaman = p_id_peminjaman;            -- kondisi_sebelum diisi trigger
END $$;

-- 7.6 Pengembalian ----------------------------------------------------
-- Dipakai untuk "Ajukan Pengembalian" (baru) dan "Ajukan Kembali" (setelah Ditolak)
CREATE FUNCTION sp_ajukan_pengembalian(p_id_peminjaman integer, p_nim varchar)
RETURNS integer LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_nim varchar; v_status status_peminjaman; v_id integer;
BEGIN
  SELECT nim, status INTO v_nim, v_status FROM peminjaman WHERE id_peminjaman = p_id_peminjaman FOR UPDATE;
  IF NOT FOUND OR v_nim <> p_nim THEN RAISE EXCEPTION 'Peminjaman tidak ditemukan'; END IF;

  IF EXISTS (SELECT 1 FROM pengembalian WHERE id_peminjaman = p_id_peminjaman AND status = 'Ditolak') THEN
    UPDATE pengembalian
       SET status = 'Menunggu', tanggal_diajukan = fn_hari_ini(), alasan_penolakan = NULL, diproses_oleh = NULL
     WHERE id_peminjaman = p_id_peminjaman
    RETURNING id_pengembalian INTO v_id;
  ELSIF v_status = 'Dipinjam' THEN
    INSERT INTO pengembalian (id_peminjaman) VALUES (p_id_peminjaman) RETURNING id_pengembalian INTO v_id;
  ELSE
    RAISE EXCEPTION 'Peminjaman tidak berstatus Dipinjam';
  END IF;
  RETURN v_id;
END $$;

CREATE FUNCTION sp_setujui_pengembalian(p_id_pengembalian integer, p_pj_nim varchar, p_jumlah integer,
                                        p_tanggal date, p_kondisi kondisi_barang, p_foto_path text,
                                        p_sanksi text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer; v_status status_pengembalian; v_jumlah integer;
BEGIN
  SELECT i.id_organisasi, g.status, p.jumlah_pinjam INTO v_org, v_status, v_jumlah
  FROM pengembalian g JOIN peminjaman p ON p.id_peminjaman = g.id_peminjaman
  JOIN inventaris i ON i.id_inventaris = p.id_inventaris
  WHERE g.id_pengembalian = p_id_pengembalian FOR UPDATE OF g;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pengembalian tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);
  IF v_status <> 'Menunggu' THEN RAISE EXCEPTION 'Pengembalian sudah diproses'; END IF;
  IF p_jumlah IS DISTINCT FROM v_jumlah THEN
    RAISE EXCEPTION 'Jumlah dikembalikan (%) tidak sesuai jumlah dipinjam (%). Gunakan Tolak jika kurang lengkap', p_jumlah, v_jumlah;
  END IF;
  UPDATE pengembalian
     SET status = 'Dikembalikan', jumlah_dikembalikan = p_jumlah, tanggal_pengembalian = p_tanggal,
         kondisi_kembali = p_kondisi, foto_kondisi_path = p_foto_path,
         sanksi = NULLIF(btrim(COALESCE(p_sanksi, '')), ''), diproses_oleh = p_pj_nim
   WHERE id_pengembalian = p_id_pengembalian;       -- trigger: inventaris.kondisi & peminjaman Selesai
END $$;

CREATE FUNCTION sp_tolak_pengembalian(p_id_pengembalian integer, p_pj_nim varchar, p_alasan text)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer; v_status status_pengembalian;
BEGIN
  SELECT i.id_organisasi, g.status INTO v_org, v_status
  FROM pengembalian g JOIN peminjaman p ON p.id_peminjaman = g.id_peminjaman
  JOIN inventaris i ON i.id_inventaris = p.id_inventaris
  WHERE g.id_pengembalian = p_id_pengembalian FOR UPDATE OF g;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pengembalian tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);
  IF v_status <> 'Menunggu' THEN RAISE EXCEPTION 'Pengembalian sudah diproses'; END IF;
  IF btrim(COALESCE(p_alasan, '')) = '' THEN RAISE EXCEPTION 'Alasan penolakan wajib diisi'; END IF;
  UPDATE pengembalian SET status = 'Ditolak', alasan_penolakan = btrim(p_alasan), diproses_oleh = p_pj_nim
  WHERE id_pengembalian = p_id_pengembalian;
END $$;

-- 7.7 Pengajuan PJ ----------------------------------------------------
CREATE FUNCTION sp_ajukan_pj(p_nim varchar, p_lampiran_path text)
RETURNS integer LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_id integer;
BEGIN
  INSERT INTO request_pj (nim, lampiran_path) VALUES (p_nim, p_lampiran_path) RETURNING id_request INTO v_id;
  RETURN v_id;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'Masih ada pengajuan PJ yang menunggu keputusan';
END $$;

CREATE FUNCTION sp_proses_request_pj(p_id_request integer, p_pj_nim varchar, p_aksi text, p_alasan text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_org integer; v_status status_request_pj;
BEGIN
  SELECT u.id_organisasi, r.status INTO v_org, v_status
  FROM request_pj r JOIN pengguna u ON u.nim = r.nim
  WHERE r.id_request = p_id_request FOR UPDATE OF r;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pengajuan PJ tidak ditemukan'; END IF;
  PERFORM fn_pastikan_pj(p_pj_nim, v_org);          -- PJ dari OKI yang sama dengan pemohon
  IF v_status <> 'Menunggu' THEN RAISE EXCEPTION 'Pengajuan sudah diproses'; END IF;

  IF lower(p_aksi) = 'setujui' THEN
    UPDATE request_pj SET status = 'Disetujui', diproses_oleh = p_pj_nim WHERE id_request = p_id_request;  -- trigger naikkan role
  ELSIF lower(p_aksi) = 'tolak' THEN
    IF btrim(COALESCE(p_alasan, '')) = '' THEN RAISE EXCEPTION 'Alasan penolakan wajib diisi'; END IF;
    UPDATE request_pj SET status = 'Ditolak', diproses_oleh = p_pj_nim, alasan_penolakan = btrim(p_alasan)
    WHERE id_request = p_id_request;
  ELSE
    RAISE EXCEPTION 'Aksi harus Setujui atau Tolak';
  END IF;
END $$;

-- ---------------------------------------------------------------------
-- 8. MATERIALIZED VIEW (laporan/dashboard manajerial untuk mata kuliah SIM)
--    Data historis agregat yang berat & boleh "agak lama" => di-cache.
--    Angka real-time (badge, kartu dashboard, kalender) TIDAK memakai MV.
-- ---------------------------------------------------------------------
CREATE MATERIALIZED VIEW mv_rekap_peminjaman_bulanan AS
SELECT i.id_organisasi AS id_organisasi_pemilik, o.singkatan AS oki_pemilik,
       date_trunc('month', p.tanggal_pengajuan)::date AS bulan,
       COUNT(*)::integer AS total_pengajuan,
       COUNT(*) FILTER (WHERE p.status IN ('Disetujui', 'Dipinjam', 'Pengembalian', 'Selesai'))::integer AS total_disetujui,
       COUNT(*) FILTER (WHERE p.status = 'Ditolak')::integer AS total_ditolak,
       COALESCE(SUM(p.jumlah_pinjam) FILTER (WHERE p.status IN ('Disetujui', 'Dipinjam', 'Pengembalian', 'Selesai')), 0)::integer AS total_unit_dipinjam,
       COUNT(*) FILTER (WHERE g.tanggal_pengembalian > p.tgl_selesai)::integer AS total_dikembalikan_terlambat
FROM peminjaman p
JOIN inventaris i ON i.id_inventaris = p.id_inventaris
JOIN organisasi o ON o.id_organisasi = i.id_organisasi
LEFT JOIN pengembalian g ON g.id_peminjaman = p.id_peminjaman AND g.status = 'Dikembalikan'
GROUP BY i.id_organisasi, o.singkatan, date_trunc('month', p.tanggal_pengajuan);
CREATE UNIQUE INDEX uq_mv_rekap ON mv_rekap_peminjaman_bulanan (id_organisasi_pemilik, bulan);

CREATE MATERIALIZED VIEW mv_barang_terpopuler AS
SELECT i.id_inventaris, i.nama_barang, k.nama_kategori, i.id_organisasi AS id_organisasi_pemilik,
       COUNT(p.id_peminjaman)::integer AS total_peminjaman,
       COALESCE(SUM(p.jumlah_pinjam), 0)::integer AS total_unit_dipinjam,
       RANK() OVER (PARTITION BY i.id_organisasi ORDER BY COUNT(p.id_peminjaman) DESC)::integer AS peringkat
FROM inventaris i
JOIN kategori k ON k.id_kategori = i.id_kategori
LEFT JOIN peminjaman p ON p.id_inventaris = i.id_inventaris
                      AND p.status IN ('Disetujui', 'Dipinjam', 'Pengembalian', 'Selesai')
WHERE i.deleted_at IS NULL
GROUP BY i.id_inventaris, k.id_kategori, k.nama_kategori;
CREATE UNIQUE INDEX uq_mv_populer ON mv_barang_terpopuler (id_inventaris);

-- PROCEDURE sungguhan (dipanggil: CALL sp_refresh_laporan();)
CREATE PROCEDURE sp_refresh_laporan()
LANGUAGE plpgsql AS $$
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY mv_rekap_peminjaman_bulanan;
  REFRESH MATERIALIZED VIEW CONCURRENTLY mv_barang_terpopuler;
END $$;

-- Jadwal otomatis (aktifkan ekstensi pg_cron di Dashboard Supabase > Database > Extensions):
-- SELECT cron.schedule('refresh-laporan-pinjemdulu', '*/30 * * * *', 'CALL public.sp_refresh_laporan()');

-- ---------------------------------------------------------------------
-- 9. KEAMANAN: RLS aktif tanpa policy + cabut akses anon/authenticated.
--    BE (koneksi Postgres langsung / service_role) tidak terpengaruh.
-- ---------------------------------------------------------------------
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
           WHERE n.nspname = 'public' AND c.relkind = 'r' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.relname);
  END LOOP;
END $$;

REVOKE ALL ON ALL TABLES    IN SCHEMA public FROM anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL ROUTINES  IN SCHEMA public FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES    FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM PUBLIC, anon, authenticated;
GRANT ALL ON ALL TABLES    IN SCHEMA public TO service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;
GRANT ALL ON ALL ROUTINES  IN SCHEMA public TO service_role;

-- ---------------------------------------------------------------------
-- 10. DATA UJI (realistis; tanggal RELATIF terhadap hari ini WIB)
--     Trigger validasi pada 4 tabel transaksi dimatikan sementara karena data
--     historis (tanggal lampau) memang tidak lolos aturan H+2. Seluruhnya dalam
--     satu transaksi: jika gagal, trigger otomatis kembali aktif (rollback).
--     Hapus/abaikan seed token 'contoh-token' pada lingkungan produksi.
-- ---------------------------------------------------------------------
BEGIN;

ALTER TABLE peminjaman        DISABLE TRIGGER USER;
ALTER TABLE pengembalian      DISABLE TRIGGER USER;
ALTER TABLE request_pj        DISABLE TRIGGER USER;
ALTER TABLE request_password  DISABLE TRIGGER USER;

