JOIN peminjaman p ON p.keperluan = v.keperluan
CROSS JOIN (SELECT fn_hari_ini() AS d) h;

INSERT INTO request_pj (nim, lampiran_path, status, tanggal_request, diproses_oleh, diproses_pada, alasan_penolakan)
SELECT v.nim, 'request-pj/' || v.nim || '/surat_rekomendasi.jpg', v.status::status_request_pj,
       fn_hari_ini() + v.aju, v.pj, now() + v.proses * interval '1 day', v.alasan
FROM (VALUES
  ('2441720011', 'Menunggu',  -1,  NULL::text,   NULL::int, NULL::text),
  ('2441720013', 'Ditolak',   -6,  '2441720002', -5,  'Lampiran surat tidak terbaca, unggah ulang'),
  ('2441720006', 'Disetujui', -40, '2441720001', -39, NULL)
) AS v(nim, status, aju, pj, proses, alasan);

